// src/components/AiCompanion.js
import React, { useState } from 'react';
import styled from 'styled-components';

const CompanionContainer = styled.div`
  margin: 20px 0;
  padding: 20px;
  border-radius: 8px;
  background-color: #f9f9f9;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
`;

const Message = styled.p`
  margin: 10px 0;
`;

const Button = styled.button`
  margin: 5px;
  padding: 10px;
  border: none;
  border-radius: 8px;
  background-color: #007bff;
  color: white;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

function AiCompanion() {
  const [step, setStep] = useState(0);

  const steps = [
    "Welcome to your Triathlon gear assistant!",
    "Let's start by selecting a bike. Choose a road bike or triathlon bike.",
    "Next, you'll need a helmet. Safety first!",
    "Don't forget proper footwear—cycling shoes and running shoes are essential.",
    "Grab a wetsuit if you'll be swimming in open water.",
    "You're all set! Add any additional accessories like water bottles and sunglasses."
  ];

  const nextStep = () => setStep((prev) => Math.min(prev + 1, steps.length - 1));
  const prevStep = () => setStep((prev) => Math.max(prev - 1, 0));

  return (
    <CompanionContainer>
      <Message>{steps[step]}</Message>
      <div>
        <Button onClick={prevStep} disabled={step === 0}>
          Previous
        </Button>
        <Button onClick={nextStep} disabled={step === steps.length - 1}>
          Next
        </Button>
      </div>
    </CompanionContainer>
  );
}

export default AiCompanion;
